conflicts AS (
  SELECT p.source_external_id,
         (c.primary_location_id IS DISTINCT FROM d.primary_location_id) AS loc_diff,
         (c.par_level IS DISTINCT FROM d.par_level)                     AS par_diff,
         (c.reorder_level IS DISTINCT FROM d.reorder_level)             AS reorder_diff,
         (c.active IS DISTINCT FROM d.active)                           AS active_diff
  FROM pairs p
  JOIN store_inventory_items d
    ON d.inventory_item_id = p.duplicate_id::uuid
  JOIN store_inventory_items c
    ON c.inventory_item_id = p.canonical_id::uuid
   AND c.store_id = d.store_id
)
SELECT
  (SELECT count(DISTINCT source_external_id) FROM conflicts)                       AS groups_with_shared_store_row,
  count(DISTINCT source_external_id) FILTER (WHERE loc_diff OR par_diff OR reorder_diff OR active_diff) AS groups_that_would_stop,
  count(DISTINCT source_external_id) FILTER (WHERE loc_diff)     AS groups_loc_diff,
  count(DISTINCT source_external_id) FILTER (WHERE par_diff)     AS groups_par_diff,
  count(DISTINCT source_external_id) FILTER (WHERE reorder_diff) AS groups_reorder_diff,
  count(DISTINCT source_external_id) FILTER (WHERE active_diff)  AS groups_active_diff
FROM conflicts;
